:root {
  color-scheme: dark;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  background: #101a2c;
  color: #f5f3e9;
  --navy: #101a2c;
  --panel: #1b2941;
  --line: #354762;
  --cream: #f5f3e9;
  --mint: #70e0b1;
  --gold: #ffc96b;
}
* { box-sizing: border-box; }
body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  padding: 32px 16px;
  display: grid;
  place-items: center;
  background: radial-gradient(ellipse at 50% 0%, #263958, var(--navy) 68%);
}
button { font: inherit; }
.board {
  width: min(100%, 760px);
  padding: clamp(20px, 5vw, 40px);
  background: var(--panel);
  border: 2px solid var(--line);
  border-radius: 18px;
  box-shadow: 0 18px 55px #080f1d88;
}
.heading { text-align: center; margin-bottom: 28px; }
.eyebrow { color: var(--mint); font-size: .8rem; font-weight: 800; letter-spacing: .15em; margin: 0 0 8px; }
h1 { font-size: clamp(2rem, 7vw, 3rem); line-height: 1.05; margin: 0; letter-spacing: -.04em; }
.subheading { color: #bac7d9; margin: 10px 0 0; }
.score-area { overflow-x: auto; padding-bottom: 6px; }
.frames { display: grid; grid-template-columns: repeat(9, minmax(50px, 1fr)) minmax(72px, 1.35fr); gap: 5px; min-width: 590px; }
.frame { min-height: 102px; overflow: hidden; border: 1px solid var(--line); border-radius: 7px; background: #142137; display: grid; grid-template-rows: 25px 35px 1fr; text-align: center; }
.frame-number { padding-top: 3px; color: #bac7d9; font-size: .82rem; font-weight: 700; border-bottom: 1px solid var(--line); }
.rolls { display: flex; justify-content: flex-end; min-height: 35px; }
.roll { min-width: 22px; padding: 6px 3px 4px; border-left: 1px solid var(--line); color: var(--cream); font-size: .9rem; font-weight: 700; }
.frame:last-child .roll { min-width: 22px; }
.frame-mark { color: var(--gold); }
.frame-score { align-self: end; padding: 4px 2px 7px; color: var(--mint); font-size: 1rem; font-weight: 800; }
.controls { margin-top: 26px; }
.turn-row { display: flex; justify-content: space-between; align-items: center; gap: 12px; }
h2 { font-size: 1.1rem; margin: 0; }
.status { color: #bac7d9; margin: 4px 0 0; min-height: 1.4em; }
.undo, .reset, .pin-button { border: 1px solid var(--line); color: var(--cream); background: #21324c; border-radius: 8px; cursor: pointer; transition: transform .08s ease, background .15s ease, border-color .15s ease; }
.undo { padding: 8px 14px; min-height: 42px; }
.undo:disabled { opacity: .45; cursor: not-allowed; }
.pin-buttons { display: grid; grid-template-columns: repeat(11, minmax(0, 1fr)); gap: 7px; margin-top: 15px; }
.pin-button { min-height: 48px; padding: 6px 2px; font-size: 1rem; font-weight: 800; }
.pin-button:hover:not(:disabled), .undo:hover:not(:disabled), .reset:hover { background: #304563; border-color: var(--mint); }
.pin-button:active:not(:disabled), .undo:active:not(:disabled), .reset:active { transform: translateY(2px); }
.pin-button:focus-visible, .undo:focus-visible, .reset:focus-visible { outline: 3px solid var(--gold); outline-offset: 3px; }
.pin-button:disabled { opacity: .35; cursor: not-allowed; }
.reset { margin-top: 12px; padding: 9px 14px; min-height: 42px; color: #bac7d9; }
.total-row { display: flex; align-items: center; justify-content: space-between; margin-top: 25px; padding: 17px 19px; border-radius: 10px; background: #142137; border: 1px solid var(--line); }
.total-row span { color: #bac7d9; font-weight: 800; letter-spacing: .12em; font-size: .85rem; }
.total-row strong { color: var(--gold); font-size: 2rem; line-height: 1; }
@media (max-width: 480px) {
  body { padding: 16px 10px; }
  .board { padding: 22px 14px; }
  .pin-buttons { gap: 4px; }
  .pin-button { min-height: 46px; }
}

const rolls = [];
const framesEl = document.getElementById('frames');
const buttonsEl = document.getElementById('pin-buttons');
const statusEl = document.getElementById('status');
const totalEl = document.getElementById('total');
const undoButton = document.getElementById('undo');

for (let pins = 0; pins <= 10; pins++) {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'pin-button';
  button.textContent = String(pins);
  button.setAttribute('aria-label', `${pins} ${pins === 1 ? 'pin' : 'pins'}`);
  button.addEventListener('click', () => addRoll(pins));
  buttonsEl.append(button);
}

document.getElementById('reset').addEventListener('click', () => {
  rolls.length = 0;
  render();
});
undoButton.addEventListener('click', () => {
  rolls.pop();
  render();
});

function frameData() {
  const frames = [];
  let index = 0;
  for (let frame = 0; frame < 10; frame++) {
    if (frame < 9) {
      if (rolls[index] === undefined) break;
      if (rolls[index] === 10) {
        frames.push({ rolls: [10], next: index + 1, complete: rolls[index + 2] !== undefined });
        index++;
      } else {
        if (rolls[index + 1] === undefined) {
          frames.push({ rolls: [rolls[index]], next: index + 1, complete: false });
          break;
        }
        frames.push({ rolls: [rolls[index], rolls[index + 1]], next: index + 2, complete: true });
        index += 2;
      }
    } else {
      frames.push({ rolls: rolls.slice(index), next: rolls.length, complete: tenthComplete(rolls.slice(index)) });
    }
  }
  return frames;
}

function tenthComplete(r) {
  if (r.length < 2) return false;
  if (r[0] === 10) return r.length >= 3;
  if (r[0] + r[1] === 10) return r.length >= 3;
  return true;
}

function addRoll(pins) {
  const frames = frameData();
  const frameIndex = frames.length;
  if (frameIndex >= 10 && frames[9]?.complete) return;
  let max = 10;
  if (frameIndex < 9 && frames[frameIndex]?.rolls.length === 1 && frames[frameIndex].rolls[0] !== 10) {
    max = 10 - frames[frameIndex].rolls[0];
  } else if (frameIndex === 9) {
    const r = frames[9]?.rolls || [];
    if (r.length === 1 && r[0] !== 10) max = 10 - r[0];
    if (r.length === 2 && r[0] === 10 && r[1] !== 10) max = 10 - r[1];
    if (r.length === 2 && r[0] + r[1] === 10 && r[0] !== 10) max = 10;
  }
  if (pins > max) return;
  rolls.push(pins);
  render();
}

function scoreFrames() {
  const result = [];
  let i = 0;
  let total = 0;
  for (let frame = 0; frame < 10; frame++) {
    if (frame < 9) {
      if (rolls[i] === undefined) break;
      let score;
      if (rolls[i] === 10) {
        if (rolls[i + 2] === undefined) { result.push(null); i++; continue; }
        score = 10 + rolls[i + 1] + rolls[i + 2];
        i++;
      } else {
        if (rolls[i + 1] === undefined) { result.push(null); break; }
        const pins = rolls[i] + rolls[i + 1];
        if (pins === 10) {
          if (rolls[i + 2] === undefined) { result.push(null); i += 2; continue; }
          score = 10 + rolls[i + 2];
        } else score = pins;
        i += 2;
      }
      total += score;
      result.push(total);
    } else {
      const tenth = rolls.slice(i);
      if (tenthComplete(tenth)) {
        total += tenth.reduce((sum, pin) => sum + pin, 0);
        result.push(total);
      } else result.push(null);
    }
  }
  return result;
}

function rollLabel(frame, slot, value) {
  if (value === undefined) return '';
  if (frame < 9 && slot === 0 && value === 10) return 'X';
  if (frame < 9 && slot === 1 && rollsForFrame(frame)[0] + value === 10) return '/';
  if (frame === 9 && slot > 0 && slot < 3 && value === 10) return 'X';
  if (frame === 9 && slot === 1 && rollsForFrame(frame)[0] + value === 10) return '/';
  return String(value);
}

function rollsForFrame(target) {
  let i = 0;
  for (let f = 0; f < target; f++) i += rolls[i] === 10 ? 1 : 2;
  return rolls.slice(i, i + (target === 9 ? 3 : 2));
}

function render() {
  const frames = frameData();
  const scores = scoreFrames();
  framesEl.replaceChildren();
  for (let frame = 0; frame < 10; frame++) {
    const data = frames[frame] || { rolls: [] };
    const card = document.createElement('div');
    card.className = 'frame';
    const number = document.createElement('div');
    number.className = 'frame-number';
    number.textContent = String(frame + 1).padStart(2, '0');
    const rollBox = document.createElement('div');
    rollBox.className = 'rolls';
    const maxSlots = frame === 9 ? 3 : 2;
    for (let slot = 0; slot < maxSlots; slot++) {
      const cell = document.createElement('span');
      cell.className = 'roll';
      const value = data.rolls[slot];
      const label = rollLabel(frame, slot, value);
      cell.textContent = label;
      if (label === 'X' || label === '/') cell.classList.add('frame-mark');
      rollBox.append(cell);
    }
    const score = document.createElement('div');
    score.className = 'frame-score';
    score.textContent = scores[frame] ?? '·';
    card.append(number, rollBox, score);
    framesEl.append(card);
  }
  const current = frameData();
  const currentIndex = Math.min(current.length, 9);
  const complete = current.length === 10 && current[9].complete;
  if (complete) {
    statusEl.textContent = 'Game complete';
    totalEl.textContent = scores[9];
  } else {
    const frame = current[currentIndex] || { rolls: [] };
    const slot = currentIndex === 9 ? frame.rolls.length : frame.rolls.length;
    statusEl.textContent = `Frame ${currentIndex + 1} · Roll ${slot + 1}`;
    totalEl.textContent = '—';
  }
  let max = 10;
  if (!complete && currentIndex < 9 && current[currentIndex]?.rolls.length === 1 && current[currentIndex].rolls[0] !== 10) max = 10 - current[currentIndex].rolls[0];
  if (!complete && currentIndex === 9) {
    const r = current[9]?.rolls || [];
    if (r.length === 1 && r[0] !== 10) max = 10 - r[0];
    if (r.length === 2 && r[0] === 10 && r[1] !== 10) max = 10 - r[1];
  }
  [...buttonsEl.children].forEach((button, pins) => { button.disabled = complete || pins > max; });
  undoButton.disabled = rolls.length === 0;
}

render();
